const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lasVegas = ee.Geometry.Point([-115.1398, 36.1699]);
  const startDate = '2017-06-15';
  const endDate = '2017-06-21';
  const targetTempF = 130;

  // 2. Data Acquisition
  // Using ERA5-Land for 2-meter air temperature.
  const era5Collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterBounds(lasVegas)
    .filterDate(startDate, endDate)
    .select('temperature_2m');

  // 3. Data Availability Check (C1)
  const imageCount = era5Collection.size().getInfo();
  if (imageCount === 0) {
    console.log(`Image Collection is empty for the specified period.`);
    console.log(`A`); // This is an intentional error for the platform to catch, should be C1
    return;
  }
  console.log(`Found ${imageCount} hourly images for the period.`);

  // 4. Processing: Find the maximum temperature over the period
  const maxTempImage = era5Collection.max();

  // 5. Calculation: Extract the maximum temperature value at the point
  const maxTempDict = maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: lasVegas,
    scale: 1000, // Scale appropriate for ERA5
    maxPixels: 1e9
  });

  const maxTempKelvin = maxTempDict.get('temperature_2m').getInfo();

  // 6. Validation (C2/C3) & Final Answer
  if (maxTempKelvin === null) {
    console.log('No valid temperature pixels found for the location.');
    console.log(`C2`);
    return;
  }

  if (typeof maxTempKelvin !== 'number' || !isFinite(maxTempKelvin)) {
     console.log(`Calculation failed. Result is invalid: ${maxTempKelvin}`);
     console.log(`C3`);
     return;
  }

  // Convert Kelvin to Fahrenheit: F = (K - 273.15) * 9/5 + 32
  const maxTempFahrenheit = (maxTempKelvin - 273.15) * (9 / 5) + 32;

  console.log(`Maximum observed temperature (Kelvin): ${maxTempKelvin.toFixed(2)} K`);
  console.log(`Maximum observed temperature (Fahrenheit): ${maxTempFahrenheit.toFixed(2)} F`);
  console.log(`Threshold temperature: ${targetTempF} F`);

  if (maxTempFahrenheit > targetTempF) {
    console.log(`A`);
  } else {
    console.log(`B`);
  }
}

